local t=Game.GetCurrentGameTurn(); local alive,dead,nocap={},{},0; for i=0,21 do local n=PlayerConfigurations[i]:GetLeaderTypeName():gsub('LEADER_JAC_',''); local p=Players[i]; if p and p:IsAlive() then local c=p:GetCities():GetCount(); local cap=p:GetCities():GetCapitalCity(); if not cap then nocap=nocap+1 end; alive[#alive+1]=n..' c'..c..(cap and '' or ' NO_CAPITAL') else dead[#dead+1]=n end end; local line='SURVIVORS T'..t..' '..#alive..'/22: '..table.concat(alive,', ')..' | DEAD: '..table.concat(dead,', '); if #alive<22 or nocap>0 then error('regression: '..line) end; return line